insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$luz$q$, $q$https://www.diariomunicipal.com.br/amm-mg/materia/110F4DAA (Dec. 2.018/2015, DOM-AMM ed. 1605, 20/10/2015)$q$, $q$Ato oficial de Luz: domínio público (Lei 9.610/1998, art. 8º, IV). Polígono da área urbana aproximado a partir do OpenStreetMap: derivado do OSM (ODbL 1.0, © colaboradores do OpenStreetMap).$q$, 2, $q$Dec. 2.018/2015: na área urbana, proibida a passagem de caminhão, carreta, romeu e julieta, bitrem, rodotrem, tritrem e treminhão carregado acima de 25 t (art. 1º; lido como PBT pela ementa) e acima de 6 m de altura (art. 2º). A área urbana não tem limite oficial georreferenciado: polígono aproximado (tecido urbano contínuo da sede no OSM, BR-262 fora).$q$);
